   108	    const week = this.week();
   109	    const earliestWeek = this.earliestWeek();
   110	    const latestCompleteWeek = this.latestCompleteWeek();
   111	    if (week === null || earliestWeek === null || latestCompleteWeek === null) {
   112	      return null;
   113	    }
   114	    return {
   115	      week,
   116	      earliestWeek,
   117	      latestCompleteWeek,
   118	      canGoToPreviousWeek: week.start > earliestWeek,
   119	      canGoToNextWeek: week.start < latestCompleteWeek,
   120	    };
   121	  });
