SP=/private/tmp/claude-501/-Users-josemejia-Documents-Software-Development-Qualitara-relay-activity-health/74b25094-c0f6-4b4a-a9ba-66244c7b622d/scratchpad; cat > $SP/verify.cjs <<'EOF'
const { chromium } = require('/Users/josemejia/Documents/Software Development/Qualitara/relay-activity-health/.claude/worktrees/agent-af1bc63b76d53c82b/web/node_modules/playwright');
const out = process.env.SP + '/implemented';
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  let hold = null;
  await page.route('**/api/activity-health**', async (route) => { if (hold) await hold; await route.continue(); });
  let release; hold = new Promise(r => release = r);
  await page.goto('http://localhost:4300/dashboard?account=14');
  await page.waitForSelector('.week-placeholder');
  const placeholderWidth = await page.$eval('.week-placeholder', e => e.getBoundingClientRect().width);
  const placeholderField = await page.$eval('.week-field', e => e.getBoundingClientRect().toJSON());
  await page.screenshot({ path: out + '/loading-v2.png', fullPage: true });
  release(); hold = null;
  await page.waitForSelector('.week-control');
  await page.waitForLoadState('networkidle');
  const control = await page.$eval('.week-control', e => ({ width: e.getBoundingClientRect().width, scroll: e.scrollWidth }));
  const loadedField = await page.$eval('.week-field', e => e.getBoundingClientRect().toJSON());
  const natural = await page.$$eval('.step', els => els.map(e => { const c = e.cloneNode(true); c.style.width = 'auto'; e.parentElement.appendChild(c); const w = c.getBoundingClientRect().width; c.remove(); return { text: e.textContent.trim(), width: e.getBoundingClientRect().width, natural: w, overflow: e.scrollWidth > e.clientWidth }; }));
  const typeFieldX = await page.$eval('.type-field', e => e.getBoundingClientRect().x);
  console.log(JSON.stringify({ placeholderWidth, placeholderField, control, loadedField, natural, typeFieldX }, null, 1));
  await page.screenshot({ path: out + '/account-14-2026-07-20-v2.png', fullPage: true });
  await page.click('app-week-picker .trigger');
  await page.waitForSelector('.week-picker-dialog');
  await page.waitForTimeout(300);
  const label = await page.$eval('.mat-calendar-period-button', e => e.innerText.trim());
  console.log('period label:', label);
  await page.screenshot({ path: out + '/picker-open-v2.png', fullPage: true });
  const url0 = page.url();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(300);
  console.log('after Enter: dialogs', await page.$$eval('.week-picker-dialog', d => d.length), 'focus on trigger', await page.evaluate(() => document.activeElement?.classList.contains('trigger')), 'url unchanged', page.url() === url0);
  await page.click('app-week-picker .trigger');
  await page.waitForSelector('.week-picker-dialog');
  await page.click('.mat-calendar-body-selected');
  await page.waitForTimeout(300);
  console.log('after click selected: dialogs', await page.$$eval('.week-picker-dialog', d => d.length), 'focus on trigger', await page.evaluate(() => document.activeElement?.classList.contains('trigger')), 'url unchanged', page.url() === url0);
  await page.click('app-week-picker .trigger');
  await page.waitForSelector('.week-picker-dialog');
  await page.click('.mat-calendar-body-cell[aria-label*="July 13"]');
  await page.waitForTimeout(500);
  console.log('after click Jul 13: dialogs', await page.$$eval('.week-picker-dialog', d => d.length), 'url', page.url());
  await browser.close();
})();
EOF
sleep 1; tail -5 $SP/serve.log; SP=$SP node $SP/verify.cjs

